INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (38, '数学', '二年级', '填空', 2, '{"stem": "辨认方向。体育馆在动物园的（ ）面，书店在学校的（ ）面，银行在邮局的（ ）面，电影院在医院的（ ）面。", "options": null}', '北，东，南，西', '布局上排：电影院 医院 体育馆；中排：邮局 广场 动物园；下排：银行 学校 书店。体育馆在动物园上方=北，书店在学校右方=东，银行在邮局下方=南，电影院在医院左方=西。', 'paper', '["期末卷", "虹口区"]', '["paper_png/yg2_sx/p106"]', 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (38, '数学', '二年级', '填空', 2, '{"stem": "像这样摆下去，第5个图形有（ ）根小棒，第8个图形有（ ）根小棒。", "options": null}', '20，32', '每个图形用4根小棒，第n个图形有4n根。第5个：4×5=20，第8个：4×8=32。', 'paper', '["期末卷", "虹口区"]', '["paper_png/yg2_sx/p106"]', 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (38, '数学', '二年级', '单选', 2, '{"stem": "一条裙子78元，欢欢带的钱都是10元的，她至少应该付（ ）。", "options": ["7张", "8张", "9张"]}', '②', '78÷10=7……8，7张只有70元不够，需要8张80元。答案②。', 'paper', '["期末卷", "虹口区"]', '["paper_png/yg2_sx/p106"]', 0, 1);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (38, '数学', '二年级', '单选', 2, '{"stem": "一个两位数，其数字和是7。如果此数减去27，那么两个数字的位置正好互换。原来的两位数是（ ）。", "options": ["61", "52", "43"]}', '②', '设十位a个位b，a+b=7，10a+b-27=10b+a → 9a-9b=27 → a-b=3 → a=5,b=2 → 52。验证：52-27=25，数字互换✓。答案②。', 'paper', '["期末卷", "虹口区"]', '["paper_png/yg2_sx/p106"]', 0, 1);
